mapper.select:

WHERE r.kind = #{kind}


        AND r.supplier_id = #{partnerId}
        AND r.customer_id = #{partnerId}


AND r.status = #{status}

    AND (r.rebate_no LIKE CONCAT('%', #{keyword}, '%') OR c.name LIKE CONCAT('%', #{keyword}, '%')
         OR s.name LIKE CONCAT('%', #{keyword}, '%'))

ORDER BY r.id DESC

SELECT COALESCE(SUM(CASE WHEN kind IN ('SALES_RETURN', 'PURCHASE_RETURN') THEN -total_amount ELSE total_amount END), 0)
FROM scm_trade_doc
WHERE partner_id = #{partnerId}

    AND kind IN ('PURCHASE_IN', 'PURCHASE_RETURN')
    AND kind IN ('SALES_OUT', 'SALES_RETURN')

  AND biz_date >= #{begin} AND biz_date <= #{end}

SELECT COALESCE(SUM(rebate_amount), 0) FROM scm_order
WHERE kind = 'SALES' AND partner_id = #{customerId}
AND id <> #{excludeOrderId}
